module multi_pipe_4bit (
	input clk,
	input rst_n,
	input [3:0] mul_a,
	input [3:0] mul_b,
	output reg [7:0] mul_out 
);

	// Extension logic for inputs
	wire [4:0] mul_a_ext;
	wire [4:0] mul_b_ext;

	assign mul_a_ext = {1'b0, mul_a}; 
	assign mul_b_ext = {1'b0, mul_b};

	// Stage 1 Registers
	reg [7:0] sum_tmp1, sum_tmp2;

	// Partial product generation
	genvar i;
	generate
		for(i = 0; i < 4; i = i + 1) begin : pp_gen_loop
			always @(posedge clk or negedge rst_n) begin
				if (!rst_n) begin
					sum_tmp1[i] <= 0;
				end else if (mul_b_ext[i]) begin
					sum_tmp1[i] <= mul_a_ext[i];
				end else begin
					sum_tmp1[i] <= 0;
				end
			end
		end
	endgenerate

	// Stage 2 Registers
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			sum_tmp2 <= 0;
		end else begin
			sum_tmp2 <= ((mul_b_ext[2] ? mul_a_ext[2] : 0) + (mul_b_ext[3] ? mul_a_ext[3] : 0)) << 2;
		end
	end

	// Final output computation
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			mul_out <= 0;
		end else begin
			mul_out <= sum_tmp1 + sum_tmp2;
		end
	end
endmodule
